script:
(function(){
  'use strict';
  const $ = (sel, root=document) => root.querySelector(sel);
  const $$ = (sel, root=document) => Array.from(root.querySelectorAll(sel));
  const search = $('#search');
  const kind = $('#kind');
  const stackTag = $('#stackTag');
  const tbody = $('#stacksTable tbody');
  const rows = $$('#stacksTable tbody tr');
  const cards = $$('article.card');
  const groups = $$('.card-group');
  const packs = $$('article.promptbox');
  const sourceRows = $$('#sourcesTable tbody tr, .sources tbody tr');
  const toast = $('#toast');
  const resultSummary = $('#resultSummary');
  let toastTimer;
  function norm(s){ return (s || '').toLowerCase(); }
  function isShown(el){ return !!el && el.style.display !== 'none' && (!el.closest('.card-group') || el.closest('.card-group').style.display !== 'none'); }
  function visibleBySearch(el,q){ return !q || norm(el.dataset.search).includes(q) || norm(el.textContent).includes(q); }
  function updateSummary(){
    const c = cards.filter(isShown).length;
    const s = rows.filter(isShown).length;
    const p = packs.filter(isShown).length;
    const r = sourceRows.filter(isShown).length;
    if(resultSummary) resultSummary.textContent = `${s} stacks · ${c} cards · ${p} packs · ${r} sources`;
  }
  function updateFilter(){
    const q = norm(search ? search.value.trim() : '');
    const k = kind ? kind.value : '';
    const st = stackTag ? stackTag.value : '';
    cards.forEach(card => {
      const okKind = !k || card.dataset.kind === k;
      const okSearch = visibleBySearch(card,q);
      card.style.display = okKind && okSearch ? '' : 'none';
    });
    groups.forEach(group => {
      const any = $$('article.card', group).some(c => c.style.display !== 'none');
      group.style.display = any ? '' : 'none';
    });
    rows.forEach(row => {
      const okTag = !st || row.dataset.tag === st;
      const okSearch = visibleBySearch(row,q);
      row.style.display = okTag && okSearch ? '' : 'none';
    });
    packs.forEach(pack => { pack.style.display = visibleBySearch(pack,q) ? '' : 'none'; });
    sourceRows.forEach(row => { row.style.display = visibleBySearch(row,q) ? '' : 'none'; });
    updateSummary();
  }
  async function copyText(text){
    const value = String(text || '').trim();
    if(!value) return;
    try { await navigator.clipboard.writeText(value); }
    catch(e){
      const area=document.createElement('textarea');
      area.value=value;
      area.setAttribute('readonly','');
      area.style.position='fixed';
      area.style.left='-9999px';
      document.body.appendChild(area);
      area.select();
      document.execCommand('copy');
      area.remove();
    }
    if(toast){
      toast.style.display='block';
      clearTimeout(toastTimer);
      toastTimer=setTimeout(()=>{ toast.style.display='none'; },1300);
    }
  }
  function formatCard(card){
    const title = $('h3', card)?.textContent.trim() || 'Directive';
    const expansion = $('.expansion', card)?.textContent.trim() || '';
    const pre = $('pre', card)?.textContent.trim() || '';
    const id = card.dataset.cardId || '';
    return `${id} — ${title}${expansion ? ' — '+expansion : ''}\n${pre}`;
  }
  function formatStack(row){
    const id = row.dataset.stackId || '';
    const cells = $$('td', row).map(td=>td.textContent.replace(/\s+/g,' ').trim());
    return `${id} — ${cells[1] || ''}\n${cells[3] || ''}`;
  }
  function formatPack(pack){
    const canonical = $('button.copy[data-copy]', pack)?.getAttribute('data-copy');
    if(canonical) return canonical;
    const id = pack.dataset.packId || '';
    const title = $('h3', pack)?.textContent.trim() || 'Pack';
    const chunks = $$('details', pack).map(d => {
      const label = $('summary', d)?.textContent.trim() || 'Variant';
      const body = $('pre', d)?.textContent.trim() || '';
      return body ? `${label}:\n${body}` : '';
    }).filter(Boolean);
    if(!chunks.length){
      const pres = $$('pre', pack).map(p=>p.textContent.trim()).filter(Boolean);
      chunks.push(...pres);
    }
    return `${id} — ${title}\n${chunks.join('\n\n')}`;
  }
  function visibleText(selector, formatter){ return $$(selector).filter(isShown).map(formatter).filter(Boolean).join('\n\n---\n\n'); }
  search?.addEventListener('input', updateFilter);
  kind?.addEventListener('change', updateFilter);
  stackTag?.addEventListener('change', updateFilter);
  $('#sortRisk')?.addEventListener('click', () => { rows.sort((a,b)=>(+b.dataset.riskRank||0)-(+a.dataset.riskRank||0) || (a.dataset.stackId||'').localeCompare(b.dataset.stackId||'')); rows.forEach(r=>tbody?.appendChild(r)); });
  $('#sortStackId')?.addEventListener('click', () => { rows.sort((a,b)=>(a.dataset.stackId||'').localeCompare(b.dataset.stackId||'')); rows.forEach(r=>tbody?.appendChild(r)); });
  $('#printBtn')?.addEventListener('click', () => window.print());
  $('#resetBtn')?.addEventListener('click', () => { if(search) search.value=''; if(kind) kind.value=''; if(stackTag) stackTag.value=''; updateFilter(); search?.focus(); });
  $('#toggleDensity')?.addEventListener('click', (ev) => { document.body.classList.toggle('compact-mode'); ev.currentTarget.textContent = document.body.classList.contains('compact-mode') ? 'Comfort view' : 'Compact view'; updateSummary(); });
  $('#expandAll')?.addEventListener('click', () => $$('article.card details').forEach(d=>{ if(isShown(d.closest('article.card'))) d.open=true; }));
  $('#collapseAll')?.addEventListener('click', () => $$('article.card details').forEach(d=>d.open=false));
  $('#collapseStackDetails')?.addEventListener('click', () => $$('#stacks details').forEach(d=>d.open=false));
  $('#collapsePackDetails')?.addEventListener('click', () => $$('#packs details').forEach(d=>d.open=false));
  $('#copyVisibleCards')?.addEventListener('click', () => copyText(visibleText('article.card', formatCard)));
  $('#copyVisibleStacks')?.addEventListener('click', () => copyText(visibleText('#stacksTable tbody tr', formatStack)));
  $('#copyVisiblePacks')?.addEventListener('click', () => copyText(visibleText('article.promptbox', formatPack)));
  $('#copyAllPacks')?.addEventListener('click', () => copyText(packs.map(formatPack).join('\n\n---\n\n')));
  $('#copyVisibleSources')?.addEventListener('click', () => copyText(sourceRows.filter(isShown).map(r=>$('.urltext',r)?.textContent.trim()).filter(Boolean).join('\n')));
  $('#copySourceKeys')?.addEventListener('click', () => copyText(sourceRows.filter(isShown).map(r=>$('.src-key',r)?.textContent.trim()).filter(Boolean).join('\n')));
  document.addEventListener('click', ev => {
    const btn = ev.target.closest('[data-copy]');
    if(!btn) return;
    copyText(btn.getAttribute('data-copy') || '');
  });
  document.addEventListener('keydown', ev => {
    const tag = (ev.target && ev.target.tagName) || '';
    const typing = ['INPUT','TEXTAREA','SELECT'].includes(tag);
    if(ev.key === '/' && !typing){ ev.preventDefault(); search?.focus(); }
    if(ev.key === 'Escape' && document.activeElement === search){ search.value=''; updateFilter(); }
  });
  updateFilter();
})();
